import React, { useMemo } from "react";

import ReactFlow, {
  Background,
  Controls,
  MiniMap,
  Handle,
  Position,
} from "reactflow";

import "reactflow/dist/style.css";

import {
  workers,
  partitions,
  topologyStatus,
} from "../data/mockData";


/* ============================================================
   KAFKA NODE
   ============================================================ */

function KafkaNode({ data }) {
  return (
    <div className="topology-node kafka-node">

      <Handle
        type="source"
        position={Position.Right}
      />

      <div className="topology-node-header">
        <span className="topology-node-title">
          Kafka
        </span>

        <span className="node-status healthy">
          ●
        </span>
      </div>

      <div className="topology-node-value">
        {data.partitionCount}
      </div>

      <div className="topology-node-label">
        Partitions
      </div>

      <div className="topology-node-status">
        ● {data.status}
      </div>

    </div>
  );
}


/* ============================================================
   WORKER POOL NODE
   ============================================================ */

function WorkerPoolNode({ data }) {
  return (
    <div className="topology-node worker-pool-node">

      <Handle
        type="target"
        position={Position.Left}
      />

      <Handle
        type="source"
        position={Position.Right}
      />

      <div className="topology-node-header">

        <span className="topology-node-title">
          Worker Pool
        </span>

        <span className="node-status healthy">
          ●
        </span>

      </div>

      <div className="topology-node-value">
        {data.workerCount}
      </div>

      <div className="topology-node-label">
        Workers
      </div>

      <div className="worker-health">

        <span className="health-item healthy">
          ● {data.healthyWorkers} Healthy
        </span>

        {data.failedWorkers > 0 && (
          <span className="health-item failed">
            ● {data.failedWorkers} Failed
          </span>
        )}

      </div>

      <div className="topology-node-hint">
        Click to inspect workers
      </div>

    </div>
  );
}


/* ============================================================
   ROCKSDB NODE
   ============================================================ */

function RocksDBNode({ data }) {
  return (
    <div className="topology-node storage-node">

      <Handle
        type="target"
        position={Position.Left}
      />

      <div className="topology-node-header">

        <span className="topology-node-title">
          RocksDB
        </span>

        <span className="node-status healthy">
          ●
        </span>

      </div>

      <div className="topology-node-label">
        State Store
      </div>

      <div className="topology-node-status">
        ● {data.status}
      </div>

    </div>
  );
}


/* ============================================================
   PROMETHEUS NODE
   ============================================================ */

function PrometheusNode({ data }) {
  return (
    <div className="topology-node metrics-node">

      <Handle
        type="target"
        position={Position.Left}
      />

      <div className="topology-node-header">

        <span className="topology-node-title">
          Prometheus
        </span>

        <span className="node-status healthy">
          ●
        </span>

      </div>

      <div className="topology-node-label">
        Metrics
      </div>

      <div className="topology-node-status">
        ● {data.status}
      </div>

    </div>
  );
}


/* ============================================================
   NODE TYPES
   ============================================================ */

const nodeTypes = {
  kafka: KafkaNode,
  workerPool: WorkerPoolNode,
  rocksdb: RocksDBNode,
  prometheus: PrometheusNode,
};


/* ============================================================
   MAIN TOPOLOGY
   ============================================================ */

function TopologyGraph() {

  /*
   * Calculate worker health from the current data.
   *
   * This will later come directly from the backend.
   */

  const healthyWorkers = workers.filter(
    (worker) => worker.status === "healthy"
  ).length;

  const failedWorkers = workers.filter(
    (worker) => worker.status === "failed"
  ).length;


  /* ----------------------------------------------------------
     Nodes
     ---------------------------------------------------------- */

  const nodes = useMemo(
    () => [

      {
        id: "kafka",

        type: "kafka",

        position: {
          x: 80,
          y: 210,
        },

        data: {
          partitionCount: partitions.length,

          status:
            topologyStatus.kafka.status,
        },
      },


      {
        id: "worker-pool",

        type: "workerPool",

        position: {
          x: 380,
          y: 180,
        },

        data: {
          workerCount: workers.length,

          healthyWorkers,

          failedWorkers,
        },
      },


      {
        id: "rocksdb",

        type: "rocksdb",

        position: {
          x: 760,
          y: 110,
        },

        data: {
          status:
            topologyStatus.rocksdb.status,
        },
      },


      {
        id: "prometheus",

        type: "prometheus",

        position: {
          x: 760,
          y: 310,
        },

        data: {
          status:
            topologyStatus.prometheus.status,
        },
      },

    ],
    [
      healthyWorkers,
      failedWorkers,
    ]
  );


  /* ----------------------------------------------------------
     Edges
     ---------------------------------------------------------- */

  const edges = useMemo(
    () => [

      {
        id: "kafka-worker-pool",

        source: "kafka",

        target: "worker-pool",

        animated: true,

        style: {
          strokeWidth: 2,
        },
      },


      {
        id: "worker-pool-rocksdb",

        source: "worker-pool",

        target: "rocksdb",

        animated: true,

        style: {
          strokeWidth: 2,
        },
      },


      {
        id: "worker-pool-prometheus",

        source: "worker-pool",

        target: "prometheus",

        animated: true,

        style: {
          strokeWidth: 2,
        },
      },

    ],
    []
  );


  return (
    <div className="topology-graph">

      <ReactFlow
        nodes={nodes}
        edges={edges}
        nodeTypes={nodeTypes}

        fitView

        fitViewOptions={{
          padding: 0.3,
        }}

        nodesDraggable={true}
        nodesConnectable={false}

        attributionPosition="bottom-left"
      >

        <Background
          gap={20}
          size={1}
        />

        <Controls />

        <MiniMap />

      </ReactFlow>

    </div>
  );
}


export default TopologyGraph;
